function d(a,b){let r=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let q=[i];for(let j=1;j<=b.length;j++)q[j]=Math.min(r[j]+1,q[j-1]+1,r[j-1]+Number(a[i-1]!==b[j-1]));r=q}return r[b.length]}

function band(a,b,k,stats={writes:0}){if(Math.abs(a.length-b.length)>k)return k+1;let prev=new Map();for(let j=0;j<=Math.min(b.length,k);j++){prev.set(j,j);stats.writes++}for(let i=1;i<=a.length;i++){let cur=new Map();for(let j=Math.max(0,i-k);j<=Math.min(b.length,i+k);j++){cur.set(j,j===0?i:Math.min(k+1,(prev.get(j)??k+1)+1,(cur.get(j-1)??k+1)+1,(prev.get(j-1)??k+1)+Number(a[i-1]!==b[j-1])));stats.writes++}prev=cur}return prev.get(b.length)??k+1}

function run(){let w=[""];for(let n=1;n<=5;n++)for(let j=0;j<2**n;j++)w.push(j.toString(2).padStart(n,"0"));let checks=0,failures=[];for(let a of w)for(let b of w)for(let k=0;k<=6;k++){checks++;let actual=band(a,b,k),expected=Math.min(d(a,b),k+1);if(actual!==expected)failures.push({a,b,k,actual,expected})}let operation_counts=[128,256,512,1024].map(n=>{let stats={writes:0};band("a".repeat(n),"a".repeat(n),1,stats);return {n,k:1,compact_state_writes:stats.writes,old_full_row_resets:n*(n+1)}});return {checks,failures,operation_counts}}
console.log(JSON.stringify(run(),null,2));
